import{_ as i,o as t,c as o,ag as n}from"./chunks/framework.8tqBsFWt.js";const d=JSON.parse('{"title":"What Winning Looks Like","description":"","frontmatter":{"title":"What Winning Looks Like","order":12},"headers":[],"relativePath":"about/chapters/12-what-winning-looks-like.md","filePath":"about/chapters/12-what-winning-looks-like.md"}'),a={name:"about/chapters/12-what-winning-looks-like.md"};function s(r,e,l,h,u,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h3 id="_12-what-winning-looks-like" tabindex="-1">12.<br>What Winning Looks Like <a class="header-anchor" href="#_12-what-winning-looks-like" aria-label="Permalink to &quot;12.&lt;br&gt;What Winning Looks Like&quot;">​</a></h3><h4 id="the-vision" tabindex="-1">The Vision <a class="header-anchor" href="#the-vision" aria-label="Permalink to &quot;The Vision&quot;">​</a></h4><p>Let&#39;s get a little bit meta — possible a bit uncomfortable — for a moment. Winning in business is simple but not easy. It&#39;s also a verb, not a noun — there is no winning moment, but a discipline of hard work, making smart bets, and no shortage of good fortune. Once we stop chasing a destination and start behaving in ways that will land us in a better place, we begin being excellent.</p><p>The only comparison worth making is to yourself. Forget comparing yourself, your company, and your people to competitors, it&#39;s a pointless waste of time that gets you nowhere and distracts from the real goal worth achieving; driving towards your own Vision, your own definition of success. There&#39;s no single image of winning except for having spent your time helping others while building an asset for yourself. You will need to remind yourself daily that your only useful comparison is &#39;am I in a better place today compared to yesterday?&#39; It&#39;s far better to be the tortoise than the hare.</p><p>In a fair race the hare beats the tortoise, wins the race. But the tortoise always finishes the race; the hare gets distracted, forgets they&#39;re in a race, runs in the wrong direction, or simply falls asleep. And when the tortoise does win the race they do so by sheer determination, earning each mile. We need ot face the reality that we are always going to face competition from hares — faster, with better engines, who are expected to win 99% of the time — but that our being tortoises, needing to be excellent to win, is a huge advantage that gives Aesop&#39;s fable its potency.</p><p>Winning is a behavior, not a measurement, but we measure that behavior in the following ways:</p><ul><li>Separation of do/own/risk</li><li>Having operating values that govern daily decisions</li><li>Trusting the Talent Siphon (celebrating when Level Fours move onto bigger and better things, excited to welcome the new incoming Level One hire)</li><li>Using Bookends to replace surveillance</li><li>Empowering through Command by Intent</li><li>Measuring LER to help make hard decisions</li><li>Operating a learning company</li></ul><p>Winning in business looks like a business that:</p><ul><li>Generates wealth without consuming the owner</li><li>Survives when a big client leaves</li><li>Adapts when AI shifts what Level One looks like</li><li>Builds succession plans through the Talent Siphon</li></ul><p>Winning in business looks like a team of people who:</p><ul><li>Become excellent through development, not grinding through decades of unenjoyably doing the bare minimum</li></ul><h5 id="you-make-a-choice-daily" tabindex="-1">You Make a Choice Daily <a class="header-anchor" href="#you-make-a-choice-daily" aria-label="Permalink to &quot;You Make a Choice Daily&quot;">​</a></h5><p>You see reality. You can keep the trap or rebuild. The path is clear but not easy. &quot;Change is inevitable; progress is optional,&quot; as John Maxwell said. Your people and your future depend on the decision.</p>',13)])])}const p=i(a,[["render",s]]);export{d as __pageData,p as default};
